float pow512(float a){
a*=a;
// ^2
a*=a;
// ^4
a*=a;
// ^8
a*=a;
// ^16
a*=a;
// ^32
a*=a;
// ^64
a*=a;
// ^128
a*=a;
// ^256
return a*a;
}
float pow1d5(float a){
return a*sqrt(a);
