}
float edgeMin(float dx_c,vec2 da, vec2 db,vec2 uv_conv){
uv_conv.x+=5.;
vec3 c = fract((round(vec3(uv_conv,uv_conv.x+uv_conv.y)))*(vec3( 0.0 , 1.0 , 2.0 )+0.61803398875));
float a1 = 1;
float a2 = textureMirror(iChannel0,vec2(c.x,0.)).x>.6?.15:1.;
float a3 = textureMirror(iChannel0,vec2(c.z,0.)).x>.6?.15:1.;
return min(min((1.0 - dx_c)*db.y*a3,da.x*a2),da.y*a1);
}
vec2 trinoise(vec2 uv_conv){
const float sq = sqrt(3./2.);
uv_conv.x *= sq;
uv_conv.y -= .5*uv_conv.x;
vec2 d = fract(uv_conv);
uv_conv -= d;
bool c = dot(d,vec2( 1.0 , 1.0 ))>1.;
vec2 dd = 1.-d;
vec2 da = c?dd:d,db = c?d:dd;
float nn = hash(uv_conv+float(c));
float n2 = hash(uv_conv+vec2( 1.0 , 0.0 ));
float n3 = hash(uv_conv+vec2( 0.0 , 1.0 ));
float nmid = mix(n2,n3,d.y);
float ns = mix(nn,c?n2:n3,da.y);
float dx = da.x/db.y;
return vec2(mix(ns,nmid,dx),edgeMin(dx,da, db,uv_conv+d));
}
vec2 map(vec3 p){
vec2 n = trinoise(p.xz);
return vec2(p.y-2.*n.x,n.y);
}
vec3 grad(vec3 p){
const vec2 e = vec2(.005, 0.0 );
float a =map(p).x;
return vec3(map(p+e.xyy).x-a
,map(p+e.yxy).x-a
,map(p+e.yyx).x-a)/e.x;
}
vec2 intersect(vec3 ro,vec3 rd){
float d=0,h=0;
vec2 ret_c=0;
for(int i = 0;i<120;i++){
// look nice with 50 iterations
vec3 p = ro+d*rd;
vec2 s = map(p);
h = s.x;
d+= h*.5;
if(abs(h)<0.005*d) {
ret_c = vec2(d,s.y);
} else {
// CONV: break unsupported, see Milkwave manual
if(d>150.|| p.y>2.) {
i=500;
}
else {
ret_c = vec2(-1, -1);
}
}
}
// end for
return ret_c;
}
void addsun(vec3 rd,vec3 ld,inout vec3 col){
float sun = smoothstep(.21,.2,distance(rd,ld));
if(sun>0.){
float yd = (rd.y-ld.y);
float a = sin(3.1*exp(-(yd)*14.));
sun *= smoothstep(-.8, 0.0 ,a);
col = mix(col,vec3(1.,.8,.4)*.75,sun);
}
}
float starnoise(vec3 rd){
float c = 0.;
vec3 p = normalize(rd)*300.;
for (float i=0.;i<4.;i++)
{
vec3 q = fract(p)-.5;
vec3 id = floor(p);
float c2 = smoothstep(.5,0.,length(q));
c2 *= step(hash21(id.xz/id.y),.06-i*i*0.005);
c += c2;
p = multiply(p*.6+.5*p, transpose(mat3(3./5., 0.0 ,4./5., 0.0 , 1.0 , 0.0 ,-4./5., 0.0 ,3./5.)));
}
c*=c;
float g = dot(sin(rd*10.512),cos(rd.yzx*10.512));
c*=smoothstep(-3.14,-.9,g)*.5+.5*smoothstep(-.3,1.,g);
return c*c;
}
vec3 gsky(vec3 rd,vec3 ld,bool mask){
float haze = exp2(-5.*(abs(rd.y)-.2*dot(rd,ld)));
float st = mask?(starnoise(rd))*(1.-min(haze,1.)):0.;
vec3 back = vec3(.4,.1,.7)*(1.-.5*textureMirror(iChannel0,vec2(.5+.05*rd.x/rd.y,0.)).x
*exp2(-.1*abs(length(rd.xz)/rd.y))
*max(sign(rd.y),0.));
