// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
uv = vec2(uv.x, -uv.y);
vec2 fragCoord  = uv;
#ifdef AA
for(float x = 0.;x<1.;x+=1./float(AA)){
for(float y = 0.;y<1.;y+=1./float(AA)){
#else
const float AA=1.,x=0.,y=0.;
#endif
// uv = (2.*(fragCoord+vec2(x,y))-uv.xy)/uv.y;
const float shutter_speed = .25;
// for motion blur
// float dt = fract(texture(iChannel0,float(AA)*(fragCoord+vec2(x,y))/uv.xy).r+uTime)*shutter_speed;
float dt = fract(hash21(float(AA)*(fragCoord+vec2(x,y)))+uTime)*shutter_speed;
jTime = uTime;
float fx = sin(uTime*0.3)*0.3;
#ifdef bass_smooth
float fy = (int)vis_version > sin(uTime*0.3)*0.3+1.1 ? 1.0 * vis_intensity+vis_shift : (0.6+0.2*bass_smooth)*vis_intensity+vis_shift;
#else
float fy = sin(uTime*0.3)*0.3+1.1;
#endif
float fz = (-20000.+jTime*speed);
vec3 ro = vec3(fx,fy,fz);
#ifdef stereo
ro+=stereo*vec3(.2*(float(uv.x>0.)-.5),0.,0.);
const float de = .9;
uv.x=uv.x+.5*(uv.x>0.?-de:de);
uv*=2.;
#endif
float dis = 1.2;
vec3 rd = normalize(vec3(uv,dis));
// vec3 rd = normalize(vec3(uv,sqrt(1.-dot(uv,uv))));
vec2 i = intersect(ro,rd);
float d = i.x;
float sunheight = .16;
float f1 = sunheight+.05*0.35*cos(jTime*0.1);
vec3 ld = normalize(vec3( 0.0 ,f1,0.7));
vec3 fog = d>0.?exp2(-d*vec3(.14,.1,.28)):vec3( 0.0 , 0.0 , 0.0 );
vec3 sky = gsky(rd,ld,d<0.);
vec3 p = ro+d*rd;
vec3 n = normalize(grad(p));
float diff = dot(n,ld)+.1*n.y;
vec3 col = vec3(.1,.11,.18)*diff;
vec3 rfd = reflect(rd,n);
vec3 rfcol = gsky(rfd,ld,true);
// floor
// col = mix(col,rfcol,.05+.95*pow(max(1.+dot(rd,n),0.),5.));
float shiny = 0.88;
col = mix(col,rfcol,.05+.95*pow(max(1.+dot(rd,n),shiny),5.));
#ifdef VAPORWAVE
col = mix(col,vec3(.4,.5,1.),smoothstep(.05,.0,i.y));
col = mix(sky,col,fog);
col = sqrt(col);
#else
col = mix(col,vec3(.8,.1,.92),smoothstep(.05, 0.0 ,i.y));
col = mix(sky,col,fog);
// no gamma for that old cg look
#endif
if(d<0.) d=1e6;
d=min(d,10.);
fragColor += vec4(clamp(col, 0.0 , 1.0 ),d<0. ? 0 : 0.1+exp2(-d));
#ifdef AA
fragColor/=float(AA*AA);
}}
#endif
ret = fragColor;
}
